// app/actions/user-analytics.ts
'use server';

import { z } from 'zod';
import { db } from '@/lib/db';
import { revalidatePath } from 'next/cache';

const UpdateMetricSchema = z.object({
  userId: z.string().uuid(),
  delta: z.number().int().min(1),
});

type ActionState = 
  | { status: 'idle' }
  | { status: 'success'; data: { updatedCount: number } }
  | { status: 'error'; message: string };

export async function incrementUserScore(
  prevState: ActionState,
  formData: FormData
): Promise<ActionState> {
  const parse = UpdateMetricSchema.safeParse({
    userId: formData.get('userId'),
    delta: Number(formData.get('delta')),
  });

  if (!parse.success) {
    return { status: 'error', message: '参数格式不合法，更新已终止' };
  }

  try {
    const record = await db.metric.update({
      where: { id: parse.data.userId },
      data: { score: { increment: parse.data.delta } },
      select: { score: true },
    });
    revalidatePath('/dashboard/metrics');
    return { status: 'success', data: { updatedCount: record.score } };
  } catch (error) {
    console.error('[MetricSyncError]', error);
    return { status: 'error', message: '数据库执行失败，请稍后重试' };
  }
}

